// Collect all scanned items
const existingItems = $('NocoDB: Bestehende Resources').item.json.data || [];
const existingKeys = new Set(existingItems.map(r => `${r.name}__${r.type}`));

const newItems = [];

// Docker containers
const dockerItems = $('Docker Scanner').all();
for (const item of dockerItems) {
  const containers = Array.isArray(item.json) ? item.json : [];
  for (const c of containers) {
    const name = (c.Names?.[0] || c.Image || 'unknown').replace('/', '');
    const key = `${name}__docker`;
    if (!existingKeys.has(key)) {
      newItems.push({ name, type: 'docker', source: 'docker.local', status: 'discovered', metadata: JSON.stringify({ image: c.Image, state: c.State }), discovered_at: new Date().toISOString() });
    }
  }
}

// OpenRouter models (top 20 newest)
const orData = $('OpenRouter Models').item.json;
const models = (orData.data || []).slice(0, 20);
for (const m of models) {
  const key = `${m.id}__model`;
  if (!existingKeys.has(key)) {
    newItems.push({ name: m.id, type: 'model', source: 'openrouter.ai', status: 'discovered', metadata: JSON.stringify({ context: m.context_length, pricing: m.pricing }), discovered_at: new Date().toISOString() });
  }
}

// Coolify apps
const coolifyApps = Array.isArray($('Coolify Apps').item.json) ? $('Coolify Apps').item.json : [];
for (const app of coolifyApps) {
  const key = `${app.name}__coolify`;
  if (!existingKeys.has(key)) {
    newItems.push({ name: app.name, type: 'coolify', source: 'coolify.automation-plus-ki.de', status: 'discovered', metadata: JSON.stringify({ status: app.status, fqdn: app.fqdn }), discovered_at: new Date().toISOString() });
  }
}

// GitHub repos
const repos = Array.isArray($('GitHub Repos').item.json) ? $('GitHub Repos').item.json : [];
for (const repo of repos) {
  const key = `${repo.full_name}__github`;
  if (!existingKeys.has(key)) {
    newItems.push({ name: repo.full_name, type: 'github', source: 'github.com', status: 'discovered', metadata: JSON.stringify({ stars: repo.stargazers_count, language: repo.language }), discovered_at: new Date().toISOString() });
  }
}

return newItems.map(item => ({ json: item }));

// Group by type for Discord embeds
const items = $input.all();
const byType = {};
for (const item of items) {
  const t = item.json.type || 'unknown';
  if (!byType[t]) byType[t] = [];
  byType[t].push(item.json.name);
}

const webhookMap = {
  docker: $env.DISCORD_WEBHOOK_DOCKER,
  model: $env.DISCORD_WEBHOOK_MODELS,
  github: $env.DISCORD_WEBHOOK_GITHUB,
  coolify: $env.DISCORD_WEBHOOK_COOLIFY,
};

const messages = [];
for (const [type, names] of Object.entries(byType)) {
  if (webhookMap[type]) {
    messages.push({
      webhook: webhookMap[type],
      payload: {
        embeds: [{
          title: `🔍 Neue ${type.toUpperCase()} Ressourcen entdeckt`,
          description: names.slice(0, 10).join('\n'),
          color: type === 'docker' ? 3447003 : type === 'model' ? 15844367 : type === 'github' ? 5763719 : 10181046,
          fields: [{ name: 'Anzahl', value: String(names.length), inline: true }, { name: 'Dashboard', value: '[Registry öffnen](https://aios.automation-plus-ki.de/agentic-os/registry)', inline: true }],
          timestamp: new Date().toISOString()
        }]
      }
    });
  }
}
return messages.map(m => ({ json: m }));
